import { Request, Response, NextFunction } from 'express';
import bcryptjs from 'bcryptjs';
import jwt from 'jsonwebtoken';
import logger from '../logger.js';
import { prisma } from '@teaching-engine/database';
import { authenticate, authorize, generateToken, generateRefreshToken } from './authenticate.js';
import { AuthenticationError, ValidationError } from './errorHandler.js';

/**
 * Comprehensive authentication middleware and utilities
 * Combines authentication, authorization, and user management
 */

// Password requirements
const PASSWORD_MIN_LENGTH = 8;
const PASSWORD_REGEX = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/;

/**
 * Hash password using bcrypt
 */
export async function hashPassword(password: string): Promise<string> {
  const saltRounds = parseInt(process.env.BCRYPT_SALT_ROUNDS || '10', 10);
  return bcryptjs.hash(password, saltRounds);
}

/**
 * Verify password against hash
 */
export async function verifyPassword(password: string, hash: string): Promise<boolean> {
  return bcryptjs.compare(password, hash);
}

/**
 * Validate password strength
 */
export function validatePasswordStrength(password: string): { isValid: boolean; errors: string[] } {
  const errors: string[] = [];

  if (password.length < PASSWORD_MIN_LENGTH) {
    errors.push(`Password must be at least ${PASSWORD_MIN_LENGTH} characters long`);
  }

  if (!PASSWORD_REGEX.test(password)) {
    errors.push('Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character');
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
}

/**
 * Login endpoint handler
 */
export async function login(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    const { email, password } = req.body;

    // Validate input
    if (!email || !password) {
      throw new ValidationError('Email and password are required');
    }

    // Find user
    const user = await prisma.user.findUnique({
      where: { email: email.toLowerCase() },
      include: {
        organization: true,
        // Include permissions if you have a permissions table
      },
    });

    if (!user) {
      // Don't reveal whether email exists
      throw new AuthenticationError('Invalid email or password');
    }

    // Check if user is active
    if (!user.active) {
      throw new AuthenticationError('Account is deactivated');
    }

    // Verify password
    const isPasswordValid = await verifyPassword(password, user.passwordHash);
    if (!isPasswordValid) {
      // Log failed attempt
      logger.warn({
        email,
        ip: req.ip,
        userAgent: req.headers['user-agent'],
      }, 'Failed login attempt');

      throw new AuthenticationError('Invalid email or password');
    }

    // Update last login
    await prisma.user.update({
      where: { id: user.id },
      data: { lastLogin: new Date() },
    });

    // Generate tokens
    const accessToken = generateToken({
      id: user.id,
      email: user.email,
      role: user.role,
      organizationId: user.organizationId || undefined,
    });

    const refreshToken = generateRefreshToken(user.id);

    // Set refresh token as HTTP-only cookie
    res.cookie('refreshToken', refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });

    // Log successful login
    logger.info({
      userId: user.id,
      email: user.email,
      ip: req.ip,
    }, 'User logged in successfully');

    res.json({
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role,
        organizationId: user.organizationId,
        organization: user.organization,
      },
      accessToken,
    });
  } catch (error) {
    next(error);
  }
}

/**
 * Register endpoint handler
 */
export async function register(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    const { email, password, name, organizationId } = req.body;

    // Validate input
    if (!email || !password || !name) {
      throw new ValidationError('Email, password, and name are required');
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      throw new ValidationError('Invalid email format');
    }

    // Validate password strength
    const passwordValidation = validatePasswordStrength(password);
    if (!passwordValidation.isValid) {
      throw new ValidationError(passwordValidation.errors.join('. '));
    }

    // Check if user already exists
    const existingUser = await prisma.user.findUnique({
      where: { email: email.toLowerCase() },
    });

    if (existingUser) {
      throw new ValidationError('Email already registered');
    }

    // Hash password
    const passwordHash = await hashPassword(password);

    // Create user
    const user = await prisma.user.create({
      data: {
        email: email.toLowerCase(),
        passwordHash,
        name,
        role: 'teacher', // Default role
        organizationId,
        active: true,
      },
      include: {
        organization: true,
      },
    });

    // Generate tokens
    const accessToken = generateToken({
      id: user.id,
      email: user.email,
      role: user.role,
      organizationId: user.organizationId || undefined,
    });

    const refreshToken = generateRefreshToken(user.id);

    // Set refresh token as HTTP-only cookie
    res.cookie('refreshToken', refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });

    // Log new registration
    logger.info({
      userId: user.id,
      email: user.email,
    }, 'New user registered');

    res.status(201).json({
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role,
        organizationId: user.organizationId,
        organization: user.organization,
      },
      accessToken,
    });
  } catch (error) {
    next(error);
  }
}

/**
 * Logout endpoint handler
 */
export async function logout(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    // Clear refresh token cookie
    res.clearCookie('refreshToken');

    // Log logout
    if (req.user) {
      logger.info({
        userId: req.user.id,
        email: req.user.email,
      }, 'User logged out');
    }

    res.json({ message: 'Logged out successfully' });
  } catch (error) {
    next(error);
  }
}

/**
 * Change password endpoint handler
 */
export async function changePassword(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    if (!req.user) {
      throw new AuthenticationError('Authentication required');
    }

    const { currentPassword, newPassword } = req.body;

    // Validate input
    if (!currentPassword || !newPassword) {
      throw new ValidationError('Current password and new password are required');
    }

    // Validate new password strength
    const passwordValidation = validatePasswordStrength(newPassword);
    if (!passwordValidation.isValid) {
      throw new ValidationError(passwordValidation.errors.join('. '));
    }

    // Get user with password hash
    const user = await prisma.user.findUnique({
      where: { id: req.user.id },
    });

    if (!user) {
      throw new AuthenticationError('User not found');
    }

    // Verify current password
    const isPasswordValid = await verifyPassword(currentPassword, user.passwordHash);
    if (!isPasswordValid) {
      throw new ValidationError('Current password is incorrect');
    }

    // Check if new password is different from current
    const isSamePassword = await verifyPassword(newPassword, user.passwordHash);
    if (isSamePassword) {
      throw new ValidationError('New password must be different from current password');
    }

    // Hash new password
    const newPasswordHash = await hashPassword(newPassword);

    // Update password
    await prisma.user.update({
      where: { id: user.id },
      data: {
        passwordHash: newPasswordHash,
        passwordChangedAt: new Date(),
      },
    });

    logger.info({
      userId: user.id,
      email: user.email,
    }, 'Password changed successfully');

    res.json({ message: 'Password changed successfully' });
  } catch (error) {
    next(error);
  }
}

/**
 * Forgot password endpoint handler
 */
export async function forgotPassword(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    const { email } = req.body;

    if (!email) {
      throw new ValidationError('Email is required');
    }

    const user = await prisma.user.findUnique({
      where: { email: email.toLowerCase() },
    });

    // Always return success to prevent email enumeration
    if (!user) {
      res.json({ message: 'If the email exists, a reset link has been sent' });
      return;
    }

    // Generate reset token
    const resetToken = jwt.sign(
      { userId: user.id, type: 'password-reset' },
      process.env.JWT_SECRET!,
      { expiresIn: '1h' }
    );

    // Store reset token (you might want to store this in database)
    // For now, we'll include it in the response (in production, send via email)
    
    logger.info({
      userId: user.id,
      email: user.email,
    }, 'Password reset requested');

    // In production, send email with reset link
    // For development, return token
    if (process.env.NODE_ENV === 'development') {
      res.json({
        message: 'Password reset token generated',
        resetToken, // Don't include in production!
      });
    } else {
      // TODO: Send email with reset link
      res.json({ message: 'If the email exists, a reset link has been sent' });
    }
  } catch (error) {
    next(error);
  }
}

/**
 * Reset password endpoint handler
 */
export async function resetPassword(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    const { token, newPassword } = req.body;

    if (!token || !newPassword) {
      throw new ValidationError('Token and new password are required');
    }

    // Verify reset token
    let decoded: any;
    try {
      decoded = jwt.verify(token, process.env.JWT_SECRET!);
    } catch (error) {
      throw new ValidationError('Invalid or expired reset token');
    }

    if (decoded.type !== 'password-reset') {
      throw new ValidationError('Invalid token type');
    }

    // Validate new password
    const passwordValidation = validatePasswordStrength(newPassword);
    if (!passwordValidation.isValid) {
      throw new ValidationError(passwordValidation.errors.join('. '));
    }

    // Hash new password
    const passwordHash = await hashPassword(newPassword);

    // Update user password
    await prisma.user.update({
      where: { id: decoded.userId },
      data: {
        passwordHash,
        passwordChangedAt: new Date(),
      },
    });

    logger.info({
      userId: decoded.userId,
    }, 'Password reset successfully');

    res.json({ message: 'Password reset successfully' });
  } catch (error) {
    next(error);
  }
}

/**
 * Session validation middleware
 */
export async function validateSession(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    if (!req.user) {
      throw new AuthenticationError('Session invalid');
    }

    // Check if password was changed after token was issued
    const user = await prisma.user.findUnique({
      where: { id: req.user.id },
      select: { passwordChangedAt: true },
    });

    if (user?.passwordChangedAt) {
      // Get token issue time
      const token = req.headers.authorization?.substring(7);
      if (token) {
        const decoded = jwt.decode(token) as any;
        const tokenIssuedAt = new Date(decoded.iat * 1000);

        if (user.passwordChangedAt > tokenIssuedAt) {
          throw new AuthenticationError('Password changed. Please login again.');
        }
      }
    }

    next();
  } catch (error) {
    next(error);
  }
}

